<?php
namespace App\Console\Commands;
use App\Models\User; use Carbon\Carbon; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Schema; use Illuminate\Support\Str;
class SendDailyEngagementPrompts extends Command {
 protected $signature='engagement:daily-prompts'; protected $description='Create timezone-aware morning and evening diary prompts.';
 public function handle(): int {if(!Schema::hasTable('engagement_preferences'))return self::SUCCESS;User::query()->whereNull('suspended_at')->chunkById(200,function($users){foreach($users as $u){$p=DB::table('engagement_preferences')->where('user_id',$u->id)->first();$tz=$p->timezone??($u->timezone??'Africa/Kampala');$now=Carbon::now($tz);$morning=substr($p->morning_time??'08:00:00',0,5);$evening=substr($p->evening_time??'20:30:00',0,5);if(($p->morning_brief_enabled??true)&&$now->format('H:i')===$morning)$this->notify($u,'Start your day','Your priorities, reminders and progress are ready.','/dashboard','mdd_morning_'.$now->toDateString());if(($p->evening_review_enabled??true)&&$now->format('H:i')===$evening)$this->notify($u,'Close your day','Take 60 seconds to review what moved forward and what should move to tomorrow.','/dashboard','mdd_evening_'.$now->toDateString());}});return self::SUCCESS;}
 private function notify($u,string $title,string $message,string $url,string $key): void {$exists=DB::table('notifications')->where('notifiable_type',$u::class)->where('notifiable_id',$u->id)->where('data','like','%"dedupe_key":"'.$key.'"%')->exists();if($exists)return;DB::table('notifications')->insert(['id'=>(string)Str::uuid(),'type'=>'App\\Notifications\\DailyEngagementPrompt','notifiable_type'=>$u::class,'notifiable_id'=>$u->id,'data'=>json_encode(['title'=>$title,'message'=>$message,'url'=>$url,'dedupe_key'=>$key]),'read_at'=>null,'created_at'=>now(),'updated_at'=>now()]);}
}
